/*
 * A aba "Notificações" do perfil (`/u/:username/notifications`): a mesma
 * lista e as mesmas abas da página /notifications (todas,
 * respostas, curtidas, chat, outras), dentro do perfil. Só no próprio perfil:
 * a API só devolve as notificações de quem pede.
 */
import app from 'flarum/forum/app';
import UserPage from 'flarum/forum/components/UserPage';
import NotificationsPageView from './NotificationsPageView';
import { umText } from './text';
export default class NotificationsUserPage extends UserPage {
  oninit(vnode) {
    super.oninit(vnode);
    this.bodyClass = 'App--notifications';
    this.loadUser(m.route.param('username'));
  }
  show(user) {
    super.show(user);
    if (this.isOwnProfile()) Promise.resolve(app.notifications.load()).catch(() => {});
  }
  isOwnProfile() {
    return !!this.user && app.session.user === this.user;
  }
  content() {
    if (!this.isOwnProfile()) return m("p", {
      className: "CanelaNotificationsPage-private"
    }, umText('page.private'));
    const slug = this.user.slug();
    return m("div", {
      className: "NotificationsPage CanelaNotificationsPage CanelaNotificationsPage--profile"
    }, NotificationsPageView(filter => app.route('user.notifications', filter ? {
      username: slug,
      filter
    } : {
      username: slug
    })));
  }
}
flarum.reg.add('ramon-canela', 'forum/usermenu/NotificationsUserPage', NotificationsUserPage);